harness_sources.idscan.py:
"""Identifier benchmark: what a page states (independent parser) versus what ECDEV extracts and resolves.
python -I idscan.py <dir with targets.json + captures> <ecdev_side> <out.json>
Source side: json.loads over every ld+json script, a plain regex pass for microdata/meta, and a visible-label
pass; check digits computed here, separately from ECDEV. ECDEV side: `trace` extraction, and a fixture
research run for the resolution identity key. Nothing is fetched."""
import json, re, sys, subprocess, pathlib, shutil, html as H, collections
d = pathlib.Path(sys.argv[1]); helper = sys.argv[2]; out = sys.argv[3]
T = json.loads((d / "targets.json").read_text())
KEYS = {"gtin": "gtin", "gtin8": "gtin8", "gtin12": "gtin12", "gtin13": "gtin13", "gtin14": "gtin14", "isbn": "isbn", "mpn": "mpn", "sku": "sku", "productid": "productID", "identifier": "identifier", "model": "model"}
def check(s):
    if not s.isdigit() or len(s) not in (8, 12, 13, 14): return False
    t = sum(int(c) * (3 if i % 2 else 1) for i, c in enumerate(reversed(s)))
    return t % 10 == 0
def walk(o, ptr, acc):
    if isinstance(o, dict):
        for k, v in o.items():
            kl = k.lower()
            if kl in KEYS and isinstance(v, (str, int, float)) and not isinstance(v, bool):
                acc.append((KEYS[kl], str(v), "JSON_LD " + ptr + "/" + k))
            elif kl in KEYS and isinstance(v, list):
                for i, x in enumerate(v):
                    if isinstance(x, (str, int)): acc.append((KEYS[kl], str(x), "JSON_LD %s/%s/%d" % (ptr, k, i)))
            walk(v, ptr + "/" + k, acc)
    elif isinstance(o, list):
        for i, x in enumerate(o): walk(x, ptr + "/%d" % i, acc)
def source_ids(text):
    acc = []
    for m in re.finditer(r'<script[^>]*type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', text, re.S | re.I):
        try: walk(json.loads(H.unescape(m.group(1)).strip()), "", acc)
        except Exception: acc.append(("UNPARSEABLE_LD_JSON", "", "JSON_LD"))
    for m in re.finditer(r'itemprop=["\'](gtin\d*|isbn|mpn|sku|productID)["\'][^>]*?content=["\']([^"\']+)', text, re.I):
        acc.append((m.group(1).lower() if m.group(1).lower() != "productid" else "productID", m.group(2), "MICRODATA_META"))
    for m in re.finditer(r'<[^>]*itemprop=["\'](gtin\d*|isbn|mpn)["\'][^>]*>([^<]{4,30})<', text, re.I):
        acc.append((m.group(1).lower(), m.group(2).strip(), "MICRODATA_TEXT"))
    for m in re.finditer(r'<meta[^>]+(?:property|name)=["\'](?:product:(?:ean|upc|gtin|isbn|mpn|retailer_item_id)|og:upc|og:ean|og:isbn)["\'][^>]*content=["\']([^"\']+)', text, re.I):
        acc.append(("meta", m.group(1), "META"))
    vis = re.sub(r"<script.*?</script>|<style.*?</style>", " ", text, flags=re.S | re.I)
    vis = H.unescape(re.sub(r"<[^>]+>", " ", vis))
    for m in re.finditer(r"(JAN(?:コード)?|EAN|GTIN|UPC|ISBN(?:-13)?|バーコード)[^0-9A-Za-z]{0,12}([0-9][0-9\- ]{6,18}[0-9])", vis, re.I):
        acc.append(("visible_" + m.group(1).lower(), m.group(2), "VISIBLE_LABEL"))
    return acc
rows = []
for t in T:
    h = t.get("http", {})
    if "file" not in h or h.get("status") != 200: continue
    raw = (d / h["file"]).read_bytes(); text = raw.decode("utf-8", "replace")
    ids = source_ids(text)
    rec = {"site": t["site"], "url": t["url"], "raw_capture_sha256": __import__("hashlib").sha256(raw).hexdigest(), "source_identifiers": []}
    for kind, val, loc in ids:
        digits = re.sub(r"[\s-]", "", val)
        e = {"kind": kind, "stated": val, "locator": loc}
        if kind in ("gtin", "gtin8", "gtin12", "gtin13", "gtin14", "isbn", "meta") or kind.startswith("visible_"):
            e["digits_only"] = val.isdigit(); e["length"] = len(digits)
            e["gtin_checksum_valid_as_stated"] = check(val) if val.isdigit() else False
            e["gtin_checksum_valid_after_stripping_separators"] = check(digits)
        rec["source_identifiers"].append(e)
    tr = json.loads(subprocess.check_output([helper, "trace", str(d / h["file"]), h.get("content_type", "text/html"), h["final_url"]]))
    rec["ecdev_products"] = [{k: p.get(k) for k in ("title", "sku", "mpn", "model", "ean", "upc", "gtin", "gtin8", "gtin14")} for p in tr.get("products", [])]
    try:
        r = json.loads(subprocess.check_output([helper, "resolve", str(d / h["file"]), h["final_url"]]))
        rec["ecdev_resolution"] = r.get("candidates", []) if r.get("ok") else {"error": r.get("error")}
    except Exception as ex:
        rec["ecdev_resolution_error"] = str(ex)[:100]
    rows.append(rec)
json.dump(rows, open(out, "w"), indent=0)
print(len(rows), "pages scanned")

harness_sources.discover_idn.py:
"""Sample product URLs from retailers' own sitemaps, under ECDEV's robots evaluator.
python -I discover.py <helper> <out seeds.json>
Per host: robots.txt -> ECDEV evaluator + AI-agent policy -> Sitemap lines -> sitemap (gz ok) ->
first child whose URL looks like a product sitemap -> 2 URLs evenly spaced. 2 s per host minimum."""
import gzip, json, re, subprocess, sys, time, urllib.parse, requests
helper, out = sys.argv[1], sys.argv[2]
UA = "ECDEV/0.1 (+read-only research)"
S = requests.Session(); S.headers["User-Agent"] = UA
HOSTS = ['www.thomann.de', 'www.conrad.de', 'www.decathlon.de', 'www.alternate.de', 'www.cyberport.de', 'www.notebooksbilliger.de', 'www.hornbach.de', 'www.obi.de', 'www.manomano.de', 'www.kaufland.de', 'www.galaxus.ch', 'www.digitec.ch', 'www.coolblue.nl', 'www.fnac.com', 'www.darty.com', 'www.screwfix.com', 'www.toolstation.com', 'www.bhphotovideo.com', 'www.sweetwater.com', 'www.guitarcenter.com', 'www.microcenter.com', 'www.samsclub.com', 'www.walgreens.com', 'www.target.com', 'www.joshin.co.jp', 'www.kojima.net', 'www.sofmap.com', 'www.monotaro.com', 'www.kohnan-eshop.com', 'www.cainz.com', 'www.honto.jp', 'books.rakuten.co.jp', 'item.rakuten.co.jp', 'www.rakuten.co.jp', 'www.tsutaya.co.jp', 'www.kinokuniya.co.jp', 'www.maruzen-publishing.co.jp', 'www.booktopia.com.au', 'www.bookdepository.com', 'www.waterstones.com', 'www.blackwells.co.uk', 'www.wob.com', 'www.thalia.de', 'www.buecher.de', 'www.orellfuessli.com', 'www.fnac.es', 'www.casadellibro.com', 'www.cdon.se', 'www.elgiganten.se', 'www.power.no', 'www.komplett.no', 'www.proshop.dk', 'www.proshop.de', 'www.mindfactory.de', 'www.caseking.de', 'www.reichelt.de', 'www.pollin.de', 'www.voelkner.de', 'www.hifi-regler.de', 'www.audio-technica.com', 'www.sennheiser-hearing.com', 'www.logitech.com', 'www.razer.com', 'www.corsair.com', 'www.gigabyte.com', 'www.jbl.com', 'www.bose.com', 'www.dyson.co.uk', 'www.philips.com', 'www.braun.de', 'www.nespresso.com', 'www.lego.com', 'www.playmobil.de', 'www.ravensburger.de', 'www.hasbro.com', 'www.mattel.com', 'www.nintendo.com', 'www.gamestop.com', 'www.gamesplanet.com', 'www.zavvi.com', 'www.hmv.com', 'www.hmv.co.jp', 'www.tower.jp', 'www.neowing.co.jp', 'www.cdjapan.co.jp', 'www.yesasia.com', 'www.hobbylink.tv', 'www.amiami.com', 'www.hlj.com', 'www.nin-nin-game.com']
def j(*a): return json.loads(subprocess.check_output([helper, *a]))
last = {}
def get(url, host):
    w = 2 - (time.time() - last.get(host, 0))
    if w > 0: time.sleep(w)
    try: r = S.get(url, timeout=25)
    except Exception as e: return None
    last[host] = time.time(); return r
seeds, log = [], []
for host in HOSTS:
    rec = {"host": host}
    r = get(f"https://{host}/robots.txt", host)
    if r is None or r.status_code != 200:
        rec["result"] = "ROBOTS_UNAVAILABLE_%s" % (r.status_code if r is not None else "ERR"); log.append(rec); continue
    pth = f"/tmp/claude-0/robots-{host}.txt"; open(pth, "w").write(r.text)
    ai = j("aipolicy", pth, "https://%s/" % host)
    if ai.get("refusal"):
        rec["result"] = "AI_AGENT_REFUSED"; rec["ai_policy"] = ai; log.append(rec); continue
    maps = re.findall(r"(?im)^\s*sitemap:\s*(\S+)", r.text)
    rec["sitemaps"] = len(maps)
    def fetch_map(u):
        rr = get(u, host)
        if rr is None or rr.status_code != 200: return None
        b = rr.content
        if b[:2] == b"\x1f\x8b":
            try: b = gzip.decompress(b)
            except Exception: return None
        return b.decode("utf-8", "replace")
    urls = []
    cand = maps[:6]
    prod = [m for m in maps if re.search(r"product|item|/p[-_]|catalog", m, re.I)]
    for m in (prod or cand)[:2]:
        t = fetch_map(m)
        if not t: continue
        locs = re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", t)
        if "<sitemapindex" in t:
            kids = [k for k in locs if re.search(r"product|item|catalog", k, re.I)] or locs
            for k in kids[:1]:
                t2 = fetch_map(k)
                if t2: urls += re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", t2)
        else: urls += locs
        if urls: break
    urls = [u for u in urls if urllib.parse.urlsplit(u).netloc == host and not u.endswith((".jpg", ".png", ".xml", ".gz"))]
    rec["urls_seen"] = len(urls)
    if len(urls) < 2: rec["result"] = "NO_PRODUCT_URLS"; log.append(rec); continue
    pick = [urls[len(urls)//7], urls[len(urls)*3//7], urls[len(urls)*5//7]]
    for u in pick: seeds.append({"site": host, "kind": "product", "url": u})
    rec["result"] = "OK"; log.append(rec)
    print(host, rec["result"], flush=True)
json.dump(seeds, open(out, "w"), indent=1); json.dump(log, open(out + ".log.json", "w"), indent=1)
print(len(seeds), "seeds")
